import {puppets,settings,actions,props,invitations,invitationById,audienceQuestions,sceneCaption} from './loft-content.mjs';
import {loftState,startShow,chooseScene,setScenePart,moveScene,performShow,stepShow,meetAudience,spotlightScene,nextAudienceQuestion,chooseAudienceQuestion,reviseShow,reopenShow,noteLoftAudio} from './loft-core.mjs';
import {sceneArt,puppetArt,propArt,backdropArt} from './loft-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,kind='secondary',disabled=false)=>`<button type="button" class="${kind}" ${attrs} ${disabled?'disabled':''}>${label}</button>`;
const kept=state=>`<section class="panel"><h2>An earlier theatre notebook is kept</h2><p>This version cannot safely change it. Download your notes to keep its original contents; all other destinations remain open.</p><a class="secondary" href="#notes">Grown-up notes and download</a></section>`;
function ideas(draft){return `<details class="loft-ideas" ${draft?'':'open'}><summary>${draft?'Begin another show':'Choose a starting idea'}</summary><p>${draft?'Your current story will go on the shelf. ':''}These are starters. Every scene can change.</p><div class="loft-invitation-strip">${invitations.map(i=>`<button class="loft-invitation" data-loft-start="${i.id}">${sceneArt(i.frames[0],true)}<strong>${i.title}</strong><span>${i.hook}</span></button>`).join('')}</div></details>`;}
function tickets(d,audience=false){return `<div class="loft-tickets" role="group" aria-label="${audience?'Choose any scene to discuss':'Your three scenes'}">${d.frames.map((f,i)=>`<button class="loft-ticket ${d.mode==='perform'&&d.stage===i?'loft-onstage':''}" ${audience?`data-loft-spotlight="${i}" aria-pressed="${d.spotlight===i}"`:`data-loft-scene="${i}" aria-pressed="${d.selected===i}"`} ${d.mode==='perform'?'disabled':''}><span class="loft-ticket-number">Scene ${i+1}</span>${sceneArt(f,true)}<span>${esc(sceneCaption(f))}</span></button>`).join('')}</div>`;}
const choiceArt=(part,id)=>part==='actor'?puppetArt(id):part==='place'?backdropArt(id):part==='prop'?propArt(id):`<span class="loft-action-mark" aria-hidden="true">${{finds:'⌕',carries:'➜',offers:'♡',plays:'♫',wonders:'?'}[id]}</span>`;
function editor(d){
 const frame=d.frames[d.selected];
 return `${tickets(d)}<div class="loft-edit-heading"><h2 id="loft-edit-title">Making scene ${d.selected+1}</h2><div class="loft-reorder">${button('data-loft-move="-1"','Move earlier','secondary',d.selected===0)}${button('data-loft-move="1"','Move later','secondary',d.selected===2)}</div></div><div class="loft-choice-groups">${[['actor','Who?',puppets],['place','Where?',settings],['action','What happens?',actions],['prop','What to bring?',props]].map(([part,title,items])=>`<fieldset><legend>${title}</legend><div class="loft-choices">${items.map(x=>`<button type="button" class="loft-choice" data-loft-part="${part}" data-loft-value="${x.id}" aria-pressed="${frame[part]===x.id}">${choiceArt(part,x.id)}<span>${x.name}</span></button>`).join('')}</div></fieldset>`).join('')}</div><p class="loft-kind-note">A dragon with a teacup? A very good place for a story to begin. Keep a surprise or try something else.</p><div class="loft-main-actions">${button('data-loft-perform','Perform our show','primary')}<span>Three scenes. You decide when each one changes.</span></div>`;
}
function performance(d){return `<div class="loft-performance-controls"><h2 id="loft-performance-title">Scene ${d.stage+1} of 3</h2><p>Tell it in your own voice, make puppet noises, or use “Hear this scene.” Move on when you’re ready.</p><div class="summary-links">${button('data-loft-step="-1"','Previous scene','secondary',d.stage===0)}${d.stage<2?button('data-loft-step="1"','Next scene','primary'):button('data-loft-audience','Meet our audience','primary')}${button('data-loft-revise','Back to making','text-button')}</div></div>${tickets(d)}`;}
function audience(d){const q=audienceQuestions[d.question];return `<section class="loft-audience"><h2 id="loft-audience-title">A question from the front row</h2><p>Our imaginary audience is curious. Every scene is welcome.</p><label for="loft-question">Choose a wondering</label><select id="loft-question">${audienceQuestions.map((q,i)=>`<option value="${i}" ${d.question===i?'selected':''}>${q.title}</option>`).join('')}</select><p class="loft-audience-question">${q.text}</p>${hearButton(q.text,'Hear the audience question')}${tickets(d,true)}${d.spotlight!==null?`<div class="loft-reflection" role="status"><p>You chose scene ${d.spotlight+1}: ${esc(sceneCaption(d.frames[d.spotlight]))}</p><p>Tell someone what you notice, act it out, or draw your idea. You can keep your story just as it is.</p></div>`:'<p class="tiny">Tap any scene above to bring it back onto the stage.</p>'}<div class="summary-links">${button('data-loft-change-scene','Change this scene','primary',d.spotlight===null)}${button('data-loft-question-next','Another audience question')}${button('data-loft-perform','Perform again')}${button('data-loft-revise','Back to making','text-button')}</div></section>`;}
function shelf(l){return `<section class="loft-shelf"><h2>Our show shelf</h2><p class="tiny">The latest 12 saved shows, plus your working story. Starting another show keeps this one here. Revisions update the same show; the shelf is not an exhaustive history.</p>${l.shelf.length?`<div class="loft-shelf-shows">${[...l.shelf].reverse().map(s=>`<button class="loft-saved-show" data-loft-open="${s.id}" ${l.draft?.id===s.id?'disabled':''}>${sceneArt(s.frames[0],true)}<span><strong>Show ${s.id} · ${esc(invitationById(s.invitation).title)}</strong><small>${l.draft?.id===s.id?'On stage now':s.shared?'Saved after a performance':'Saved while making'}${l.draft?.id===s.id?'':' · Open this show'}</small></span></button>`).join('')}</div>`:'<p>Finish a performance or begin another story, and a show will have a place here.</p>'}</section>`;}
export function loftPage(state){
 const l=loftState(state);if(!l)return kept(state);const d=l.draft,index=d?.mode==='edit'?d.selected:d?.stage,frame=d?.frames[index]||invitations[0].frames[0];
 return `<div class="loft-room"><div class="page-heading"><a class="back" href="#home">← Back to the garden</a><h1>Story Loft</h1><p>The storm scattered the library puppets. Now our neighbors are ready for a little show. Make three scenes, perform them, and see where your ideas take you.</p>${!d?hearButton('Choose a starting idea. Pick who is in each scene, where they are, what happens, and a prop. Perform your three scenes at your own pace. Every surprising combination is welcome.','Hear how to make a show'):''}</div>${d?.mode==='edit'?'<div class="loft-workbench">':''}<div class="loft-main-stage">${sceneArt(frame)}<p class="loft-caption" id="loft-caption" tabindex="-1">${d?esc(sceneCaption(frame)):'A small stage. A whole world to imagine.'}</p>${d?hearButton(sceneCaption(frame),'Hear this scene'):''}</div>${d?`<div class="loft-making"><p class="loft-starter-note">Starting idea: ${esc(invitationById(d.invitation).title)}. These are starter scenes; keep or change every choice.</p>${d.mode==='edit'?editor(d):d.mode==='perform'?performance(d):audience(d)}</div>`:''}${d?.mode==='edit'?'</div>':''}${ideas(d)}${shelf(l)}<section class="loft-journeys"><h2>Where could your story go?</h2><p>Tell it with your voice, draw it, or write it on paper. These invitations stay open.</p><div class="summary-links"><a class="secondary" href="#words">Find a word for your story</a><a class="secondary" href="#paris">Meet another storyteller</a><a class="secondary" href="#cafe">A café snack for the audience</a></div></section><details class="loft-grownups"><summary>Grown-ups: what this little stage practices</summary><p>Choosing characters, settings and events; revisiting a sequence for an audience. Captions are supplied from finite word choices. Discussion and off-screen stories are unobserved. This does not assess independent writing, retelling, reading, spelling, or story quality.</p><a href="#notes">Open the private notebook</a></details></div>`;
}
export function loftNotes(state){
 if(!Object.hasOwn(state,'loft'))return '';const l=loftState(state);
 if(!l)return `<details class="panel"><summary>Story Loft: an earlier notebook is kept</summary><p>Unavailable format retained without changes; included in notes downloads.</p><pre>${esc(JSON.stringify(state.loft,null,2))}</pre></details>`;
 const shows=[...l.shelf.filter(s=>s.id!==l.draft?.id),...(l.draft?[l.draft]:[])];
 return `<details class="panel"><summary>Story Loft: picture stories and revision</summary><p>Finite tap-composed pictures and supplied phrases. Shows, scene edits and requested narration record participation only. No correct/independent score, oral retelling, original writing, reading level or discussion response is inferred. Shelf keeps 12 snapshots plus the draft.</p>${shows.map(s=>`<article><h3>Show ${s.id}: ${esc(invitationById(s.invitation).title)}</h3><p>${s.changes} scene edits/reorders. Current arrangement ${s.shared?'saved after stepping through the performance':'not yet shared through a full performance'}. Narration requested: ${s.heard?'yes':'no'}. ${l.draft?.id===s.id?'Working show.':''}</p><ol>${s.frames.map(f=>`<li>${esc(sceneCaption(f))}</li>`).join('')}</ol></article>`).join('')}<a href="#loft">Return to the little stage</a></details>`;
}
export function bindLoft(state,ctx){
 const change=(fn,selector,animate=false)=>{if(!fn())return;ctx.save();ctx.render();if(animate)document.querySelector('[data-loft-stage]')?.classList.add('loft-acted');if(selector)ctx.focus(selector);};
 document.querySelectorAll('[data-loft-start]').forEach(b=>b.onclick=()=>change(()=>startShow(state,b.dataset.loftStart),'#loft-edit-title'));
 document.querySelectorAll('[data-loft-scene]').forEach(b=>b.onclick=()=>change(()=>chooseScene(state,Number(b.dataset.loftScene)),'#loft-edit-title'));
 document.querySelectorAll('[data-loft-part]').forEach(b=>b.onclick=()=>change(()=>setScenePart(state,b.dataset.loftPart,b.dataset.loftValue),`[data-loft-part="${b.dataset.loftPart}"][data-loft-value="${b.dataset.loftValue}"]`,true));
 document.querySelectorAll('[data-loft-move]').forEach(b=>b.onclick=()=>change(()=>moveScene(state,Number(b.dataset.loftMove)),'#loft-edit-title'));
 document.querySelectorAll('[data-loft-perform]').forEach(b=>b.onclick=()=>change(()=>performShow(state),'#loft-performance-title',true));
 document.querySelectorAll('[data-loft-step]').forEach(b=>b.onclick=()=>change(()=>stepShow(state,Number(b.dataset.loftStep)),'#loft-performance-title',true));
 document.querySelector('[data-loft-audience]')?.addEventListener('click',()=>change(()=>meetAudience(state),'#loft-audience-title'));
 document.querySelectorAll('[data-loft-spotlight]').forEach(b=>b.onclick=()=>change(()=>spotlightScene(state,Number(b.dataset.loftSpotlight)),'.loft-reflection'));
 document.querySelector('[data-loft-question-next]')?.addEventListener('click',()=>change(()=>nextAudienceQuestion(state),'#loft-audience-title'));
 document.querySelector('#loft-question')?.addEventListener('change',e=>change(()=>chooseAudienceQuestion(state,Number(e.target.value)),'#loft-audience-title'));
 document.querySelector('[data-loft-change-scene]')?.addEventListener('click',()=>change(()=>reviseShow(state,loftState(state)?.draft.spotlight),'#loft-edit-title'));
 document.querySelectorAll('[data-loft-revise]').forEach(b=>b.onclick=()=>change(()=>reviseShow(state),'#loft-edit-title'));
 document.querySelectorAll('[data-loft-open]').forEach(b=>b.onclick=()=>change(()=>reopenShow(state,Number(b.dataset.loftOpen)),'#loft-edit-title'));
 document.querySelectorAll('.loft-room [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(noteLoftAudio(state))ctx.save();}));
}
